const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const lakeUrmia = ee.Geometry.Polygon([
        [
            [45.16, 37.81],
            [45.68, 37.81],
            [45.68, 37.50],
            [45.16, 37.50],
            [45.16, 37.81]
        ]
    ]);
    const date1_start = '2016-07-18';
    const date1_end = '2016-07-19';
    const date2_start = '2016-04-23';
    const date2_end = '2016-04-24';

    // 2. Data Acquisition & Processing Function
    const getWaterRedness = function(startDate, endDate, geometry) {
        // Use Sentinel-2 Level-2A for Surface Reflectance and Scene Classification
        const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(geometry)
            .filterDate(startDate, endDate);

        const imageCount = collection.size().getInfo();
        if (imageCount === 0) {
            return {
                redness: null,
                count: 0,
                imageCount: 0
            };
        }

        const image = collection.first();
        const scl = image.select('SCL');
        // Mask for water pixels only (SCL class 6)
        const waterMask = scl.eq(6);
        const maskedImage = image.updateMask(waterMask);

        const scale = 1000;
        const stats = maskedImage.select('B4').reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: scale,
            maxPixels: 1e9
        });

        // Use ee.Number for server-side handling of potential nulls
        const redness = ee.Number(stats.get('B4_mean'));
        const count = ee.Number(stats.get('B4_count'));

        return {
            redness: redness.getInfo(),
            count: count.getInfo(),
            imageCount: imageCount
        };
    };

    // 3. Calculation for both dates
    const julyData = getWaterRedness(date1_start, date1_end, lakeUrmia);
    const aprilData = getWaterRedness(date2_start, date2_end, lakeUrmia);

    // 4. Validation & Final Answer
    console.log(`July 2016 Images: ${julyData.imageCount}`);
    console.log(`April 2016 Images: ${aprilData.imageCount}`);

    if (julyData.imageCount === 0 || aprilData.imageCount === 0) {
        console.log("Evidence: No images found for one or both dates.");
        console.log("C1");
        return;
    }

    console.log(`July 2016 Water Pixels: ${julyData.count}`);
    console.log(`April 2016 Water Pixels: ${aprilData.count}`);

    if (julyData.count === 0 || aprilData.count === 0) {
        console.log("Evidence: Found images but no valid water pixels after masking.");
        console.log("C2");
        return;
    }

    // Check if results are null/undefined after getInfo()
    if (julyData.redness === null || aprilData.redness === null) {
        console.log("Evidence: Calculation returned a null value.");
        console.log("C3");
        return;
    }

    // Surface Reflectance values are scaled by 10000
    const julyRedness = julyData.redness;
    const aprilRedness = aprilData.redness;

    console.log(`July 18, 2016 Mean Redness (B4): ${julyRedness.toFixed(2)}`);
    console.log(`April 23, 2016 Mean Redness (B4): ${aprilRedness.toFixed(2)}`);

    if (julyRedness < aprilRedness) {
        console.log("Evidence: July redness is lower than April redness.");
        console.log("A");
    } else {
        console.log("Evidence: July redness is not lower than April redness.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('Authentication or Initialization failed:');
        console.error(e);
        console.log("D");
    }
}

initEE();
